-- =====================================================================
-- 0047 — Central de Documentos (importada do Notion) + tabela do módulo
-- "Documentos": links de planilhas, modelos e controles do marketing.
-- Leitura: todos os usuários autenticados. Escrita: liderança.
-- Importação do Notion: 39 itens; pode rodar mais de uma vez (usa notion_id).
-- Rode DEPOIS da 0046.
-- =====================================================================

create table if not exists central_documentos (
  id uuid primary key default gen_random_uuid(),
  notion_id text unique,
  nome text not null,
  categoria text not null default 'Outros',
  url text,
  notion_url text,
  criado_por uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now()
);
create index if not exists central_documentos_categoria_idx on central_documentos (categoria, nome);

alter table central_documentos enable row level security;

drop policy if exists "central_documentos_select" on central_documentos;
create policy "central_documentos_select" on central_documentos
  for select using (auth.uid() is not null);
drop policy if exists "central_documentos_insert" on central_documentos;
create policy "central_documentos_insert" on central_documentos
  for insert with check (public.eh_lideranca());
drop policy if exists "central_documentos_update" on central_documentos;
create policy "central_documentos_update" on central_documentos
  for update using (public.eh_lideranca());
drop policy if exists "central_documentos_delete" on central_documentos;
create policy "central_documentos_delete" on central_documentos
  for delete using (public.eh_lideranca());

insert into central_documentos (notion_id, nome, categoria, url, notion_url)
select t.notion_id, t.nome, t.categoria, t.url, t.notion_url
